initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing a set of Context Source Registration Subscriptions (CSRSs)
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Update Context Source Registration Subscription with Response Status Code set to 400     and
        Update Context Source Registration Subscription with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/BadRequestData'     and
        Update Context Source Registration Subscription with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceSubscriptions/{subscription_id}'
        method set to 'PATCH'
        Update Context Source Registration Subscription with subscription id set to '${subscription_id}' and subscription update fragment set to '${subscription_update_fragment}'
}

